function singleNumber(nums: number[]): number {
  // Для каждого бита считаем, сколько раз он встретился, по модулю 3.
  // Счётчик 0..2 кодируется двумя масками:
  //   ones — биты, встреченные 1 раз (mod 3)
  //   twos — биты, встреченные 2 раза (mod 3)
  let ones = 0;
  let twos = 0;

  for (const num of nums) {
    // Бит попадает в ones, если его ещё нет в twos (переход 0 -> 1 или 1 -> 0 через XOR)
    ones = (ones ^ num) & ~twos;
    // Бит попадает в twos, если он только что ушёл из ones (переход 1 -> 2),
    // а третье появление обнуляет его в обеих масках (2 -> 0)
    twos = (twos ^ num) & ~ones;
  }

  // Биты, встретившиеся 3k + 1 раз, — это биты единственного числа.
  // Битовые операции в JS работают с 32-битными знаковыми числами,
  // поэтому отрицательные значения восстанавливаются автоматически
  return ones;
}

// Время: O(n)
// Память: O(1)
